BEGIN;

UPDATE public.questions q
SET explanation_data = q.explanation_data || v.value
FROM jsonb_each('{"gh200-q1": {"point": "on.scheduleのcronで「毎日〇時」なら、左端(分)→次(時)の順に''0 2 * * *''のように書く。時刻は日本時間ではなくUTCで指定する。", "why_asked": "cronの5フィールドの順序を勘違いしたまま覚えている人が多く、実務では日本時間とUTCの9時間ズレに気づかず「思った時刻に動かない」事故が起きやすいから。分と時の位置を逆にする典型ミスも試験で狙われる理由。", "kid": "目覚まし時計と同じで「分→時」の順に数字を並べるだけ。あとは全部*(毎回)にすれば毎日決まった時刻に起動する。", "eg": "駅の時刻表に「02:00発」と書く代わりに、GitHub Actionsでは「0 2」の順で書く。書く順番さえ覚えておけば迷わない。"}, "gh200-q2": {"point": "matrixの一部が落ちても残り全部を最後まで走らせたいなら、strategy直下にfail-fast: falseを置く。", "why_asked": "fail-fastの既定値がtrueであることを知らないと「なぜ他の組み合わせまで巻き込まれて中断されたのか」原因が分からず詰まる。continue-on-errorと役割が違う(効く範囲がジョブ全体か1ステップか)点の混同も頻出。", "kid": "何もしなければ、1つのバージョンでテストが落ちた瞬間に他のバージョンのテストも巻き添えで止まる。falseにすると「他は気にせず最後までやって」と言える。", "eg": "合唱の練習で1人が音を外しても指揮者が「止めない、最後まで通して」と言うようなもの。fail-fast: falseはこの指示にあたる。"}, "gh200-q3": {"point": "AのジョブがBのジョブの実行条件になるなら、Bのジョブ定義にneeds: Aを書く。", "why_asked": "ジョブは既定で並列実行されることを知らないと「順番に実行されるはず」という思い込みで詰まる。depends-onやafterのような他ツールでよく見る単語と混同しやすい。", "kid": "何も指定しなければジョブは同時にバラバラに始まる。needsを書いた分だけ「先に終わらせておいてほしい相手」を指定できる。", "eg": "引っ越し作業で「荷造りが終わってからトラックに積む」という順番を紙に書いておくようなもの。needsがその順番書きにあたる。"}, "gh200-q4": {"point": "workflow_dispatchで手動入力した値を使うなら、inputs.<名前>で参照する。env/secrets/varsとは値の出どころが違う別の箱。", "why_asked": "${{ }}の中に出てくるenv/secrets/vars/inputsはどれも見た目が似ているため、値の出どころ(誰がどこで設定したか)で区別できないと混同する。試験では入力元に応じた正しいコンテキスト選択が繰り返し問われる。", "kid": "手動実行のフォームに入れた値は、フォーム専用の受け取り箱(inputs)からしか取り出せない。他の箱(env/secrets/vars)には自動で入らない。", "eg": "郵便受けが複数あるアパートで、自分宛の荷物は自分の郵便受け(inputs)にしか届かない。隣の郵便受け(env)を覗いても入っていない。"}, "gh200-q5": {"point": "呼び出し元のシークレットを全部そのまま渡したいなら、reusable workflow呼び出しのsecrets: inheritを使う。", "why_asked": "シークレットを個別に列挙する書き方(secrets: にname: 値を並べる)しか知らないと、多数のシークレットを持つワークフローで書き漏れが起きる。inheritという専用キーワードの存在を知っているかが問われる。", "kid": "シークレットを1個ずつ手渡す代わりに「持ってるもの全部渡すね」とまとめて渡せる特別な合図がinherit。", "eg": "出張に行く後輩に、必要な経費だけ小分けに渡すのではなく「会社のカードごと持っていって」と渡すようなもの。"}, "gh200-q6": {"point": "同じgroupで新しいrunが来たら古いrunを打ち切りたいなら、concurrency.cancel-in-progress: trueを使う。", "why_asked": "concurrencyのgroup(誰を同じ仲間とみなすか)とcancel-in-progress(その中でどう振る舞うか)を分けて理解していないと、matrix専用のfail-fastと混同する。連続pushでrunが積み上がる実務のムダ排除に直結するため頻出。", "kid": "同じグループ名のrunが新しく始まったら、前の実行中のrunを止めて最新だけ残す設定。", "eg": "同じエレベーターを何度も呼ぶと、最初の呼び出しは無視されて最後に押した階だけが有効になるのと同じ。"}, "gh200-q7": {"point": "同じ名前の環境変数がworkflow/job/stepで重複したら、一番内側(step)の値が勝つ。", "why_asked": "「上位(workflow)の設定の方が強いはず」という直感的な誤解をする人が多い。実務でも共通設定を上書きするつもりでstepにenvを書いたら意図通り上書きされた、逆に「なぜ上書きされないのか」で詰まる原因になる。", "kid": "一番近く(step)に書いた値がそのまま使われる。遠く(workflow)の値は近くに書いた分だけ上書きされる。", "eg": "家族全体のルール(workflow)より自分の部屋の張り紙(step)が優先されるようなもの。近い方の指示が勝つ。"}, "gh200-q8": {"point": "起動したイベントの種類(push/pull_requestなど)で条件分岐したいなら、github.event_nameを使う。github.refはブランチ名で別物。", "why_asked": "event_nameとrefはどちらもgithubコンテキストの中にある似た並びの値のため、「イベント種別の判定」に誤ってrefを使ってしまうミスが実務でも起きやすい。", "kid": "「何のイベントで来たか」を知りたいときはevent_name、「どのブランチ・タグから来たか」を知りたいときはrefを見る。", "eg": "受付で「ご用件は何ですか(event_name)」と「どちらの入口からいらっしゃいましたか(ref)」は別の質問。片方を聞いてももう片方の答えにはならない。"}, "gh200-q9": {"point": "別ジョブ(別ランナー)にファイルを確実に渡したいなら、upload-artifactで預けてdownload-artifactで受け取る。", "why_asked": "同じrun内だから当然ファイルが共有されると誤解しがち。実際はジョブごとに別のマシン(ランナー)が割り当たるため、この橋渡しの仕組みを知らないと「なぜファイルが見つからないのか」で詰まる。outputsやcacheとの用途の違いも狙われる。", "kid": "ジョブが変わると使うマシンも変わるので、ファイルはそのままでは渡らない。一度預けて(upload)、別のジョブで受け取る(download)必要がある。", "eg": "別々の部屋で作業する2人が、机の上のメモを直接渡せず、一度ロッカーに預けてから相手が取り出すようなもの。"}, "gh200-q10": {"point": "詳細なデバッグログを出したいなら、YAMLではなくリポジトリのシークレット/変数側でACTIONS_STEP_DEBUGをtrueに設定する。", "why_asked": "「debug: trueのようなYAMLキーがあるはず」という思い込みで探してしまう人が多い。実際の設定場所がYAMLの外(リポジトリ設定)にあるという置き場所のズレを知っているかが問われる。", "kid": "ログを詳しくするスイッチは、ワークフローファイルの中ではなく、リポジトリの設定画面(Secrets/Variables)にある。", "eg": "テレビの詳細設定が、番組内(YAML)ではなくリモコンの設定メニュー(リポジトリ設定)にあるようなもの。"}, "gh200-q11": {"point": "Re-run failed jobsは失敗したジョブと、それに依存する後続ジョブだけを再実行する。全ジョブのやり直しではない。", "why_asked": "「failed」という単語から「失敗した部分だけ」という理解に留まりがちだが、needsで繋がる後続ジョブも巻き込まれる点を知らないと、再実行の挙動を誤解して混乱する。", "kid": "間違えたところだけやり直すが、その結果に影響される後ろの工程も一緒にやり直す。成功済みの独立した部分はそのまま残る。", "eg": "テストで間違えた問題を解き直すとき、その答えを使う次の問題(連動問題)も一緒に解き直す必要があるのと同じ。"}, "gh200-q12": {"point": "run結果ページにMarkdownの表を出したいなら、$GITHUB_STEP_SUMMARYファイルに追記する。", "why_asked": "標準出力(echo)はログに出るだけでサマリ画面には反映されないという区別ができていないと、「なぜechoしたのに表示されないのか」で詰まる。set-outputという旧式の仕組みとの混同も狙われる。", "kid": "ログに流れる内容とサマリ画面に貼り出される内容は別物。サマリに出したい内容だけ専用のファイル($GITHUB_STEP_SUMMARY)に書き込む。", "eg": "独り言(標準出力)はその場で消えていくが、掲示板の専用の投函口(サマリ)に貼った紙は後からみんなが見られる。"}, "gh200-q13": {"point": "1つのステップが失敗してもジョブ全体は成功扱いで続けたいなら、そのステップにcontinue-on-error: trueを付ける。", "why_asked": "他のCIツール(GitLab CIのallow-failureなど)を触ったことがあると用語を混同しやすい。fail-fast(matrix専用)との対象範囲の違いも頻出の引っかけ。", "kid": "「ここで転んでも気にせず先に進んでいい」という許可を、失敗してもいい特定のステップにだけ与える。", "eg": "リハーサルで一部の演目を失敗しても本番進行を止めない、というルールを決めておくようなもの。"}, "gh200-q14": {"point": "複数のシェルコマンドをまとめて部品化したいだけ(追加のランタイム不要)なら、Composite actionを選ぶ。", "why_asked": "3種類あるアクション(JavaScript/Docker/Composite)の使い分けは、要件(何を必要とするか)から逆算して選ぶ判断力が問われる。「ジョブ丸ごとの再利用」であるreusable workflowとの粒度の違いも頻出の混同ポイント。", "kid": "ただのシェルの手順をまとめたいだけなら、新しい道具(Node環境やコンテナ)は要らない。一番身軽なcompositeで十分。", "eg": "よく使う手順書をコピー用テンプレにまとめる感覚。特別な機材(Node/Docker)を新しく用意する必要はない。"}, "gh200-q15": {"point": "JavaScript actionのランタイム指定は、2026年時点でサポートされている世代(node20)を選ぶ。古い世代(node12など)はサポート終了済み。", "why_asked": "GitHub ActionsのNode世代は定期的に更新され古いバージョンはサポート終了になるため、試験でも「その時点の現行世代」を正しく把握しているかが問われる。javascriptという値やcompositeとの混同も狙われる。", "kid": "アクションを動かすNodeのバージョンを指定する欄。今使えるバージョンを選べばよい。", "eg": "家電を動かす電源の規格のようなもの。古い規格(node12)はもう対応終了しているので、今のコンセント(node20)に合わせる。"}, "gh200-q16": {"point": "composite actionの出力を外へ渡したいなら、ステップ側で$GITHUB_OUTPUTに書き込み、action.ymlのoutputsでsteps.<id>.outputs.<name>を参照する、の両方が必要。", "why_asked": "「outputsを書けば自動的に外に伝わる」という誤解をしやすい。実際はステップ側の書き込みとaction.yml側の紐付けという2段階が必要で、片方だけでは動かない点が問われる。", "kid": "中の作業者が結果をメモに書くだけでは外に伝わらない。「このメモを外に渡します」と受付が宣言して初めて外から見える。", "eg": "社内資料(ステップの$GITHUB_OUTPUT)を作っただけでは社外秘のまま。広報部(action.ymlのoutputs)が「これは公開します」と宣言して初めて外部に届く。"}, "gh200-q17": {"point": "自作アクションの利用者を@v1のまま安全に更新へ追従させたいなら、semverタグ(v1.2.3)を打ちつつ、動くメジャータグv1を最新の互換コミットへ貼り替え続ける。", "why_asked": "「バージョン固定=安全」という利用側の視点(問29のSHA固定)と、「提供側がどう運用してユーザーに更新を届けるか」という視点は逆方向であり、この2つを混同しやすい。試験ではどちらの立場からの問いかを見極める力が問われる。", "kid": "利用者はv1を指定したまま使い続けられるように、提供側が裏でv1タグを最新の中身に更新し続ける。", "eg": "雑誌の「最新号コーナー」という棚(v1)に毎回新しい号を置き換えていくお店のようなもの。読者は棚の場所さえ覚えていれば最新版が手に入る。"}, "gh200-q18": {"point": "Marketplaceでの見た目(アイコン・色)を設定したいなら、action.ymlのbranding(icon/color)を使う。", "why_asked": "marketplace/display/metadataのようなそれらしい名前のキーは実在せず、正確なキー名(branding)を覚えているかがそのまま問われる典型パターン。", "kid": "action.ymlの中の「見た目担当」の欄がbranding。アイコンと色をここで決める。", "eg": "商品パッケージのデザイン欄に、ロゴ(icon)と色(color)を書き込むようなもの。"}, "gh200-q19": {"point": "同一リポジトリ内のローカルアクション(uses: ./...)を呼ぶなら、その前にactions/checkoutでリポジトリを取得しておく必要がある。", "why_asked": "ランナーは何も無い空の状態から始まるという前提を忘れると、「ファイルが見つからない」エラーの原因が分からなくなる。setup-nodeや権限設定など無関係な選択肢に惑わされやすい。", "kid": "ランナーは最初は空っぽの部屋。リポジトリの中身(ローカルアクションのファイルも含む)を持ってくる(checkout)まで、そのファイルは存在しない。", "eg": "引っ越し先の新居(ランナー)に、まだ荷物(リポジトリの中身)を運び込んでいなければ、家にあるはずの道具は使えない。"}, "gh200-q20": {"point": "特定のラベルを持つself-hosted runnerを狙うなら、runs-on: [self-hosted, ラベル名]と配列で書く(全部満たすAND条件)。", "why_asked": "GitHub-hosted風の名前(gpu-latestなど)が選択肢に混ざりやすく、「それらしい名前」に釣られず「self-hosted+カスタムラベルの組み合わせ」という正しい構文を知っているかが問われる。配列がAND条件だと知らないと絞り込みの意図を誤解する。", "kid": "欲しい条件(自前マシンであること、GPUがあること)を全部並べて書くと、その全部を満たすランナーだけが選ばれる。", "eg": "求人条件で「経験者、かつ、土日勤務可」と両方書くと、両方満たす人だけが応募対象になるのと同じ。"}, "gh200-q21": {"point": "Organization管理のself-hosted runnerを特定リポジトリだけに使わせたいなら、Runner groupを作りアクセス可能なリポジトリを限定する。", "why_asked": "Secrets/permissions/ブランチ保護は名前が似た管理系機能として並んで見えるため、それぞれが制御する対象(値/トークン権限/マージ条件/ランナーアクセス)を混同しやすい。「どの機能が何を制御するか」の対応関係の正確な理解が問われる。", "kid": "ランナーという実行環境そのものへの出入りを管理する専用の仕組みがRunner group。使えるリポジトリを絞り込める。", "eg": "会社の特定の部屋(ランナー群)に、入館証を持つ部署(指定リポジトリ)だけが入れるようにするようなもの。"}, "gh200-q22": {"point": "Organizationの許可ポリシーで実在する軸は「GitHub公式作成」「検証済み作成者」「名指しの許可リスト」の3つ。個人のメールアドレスで許可する仕組みは存在しない。", "why_asked": "複数選択問題では「それらしいが存在しない選択肢」を見分ける力が特に問われる。メールアドレスという個人単位の基準は、リポジトリ・組織単位で管理されるActionsの許可ポリシーの粒度と合わないと気づけるかがポイント。", "kid": "許可する・しないは「誰が作ったか(公式/検証済み/名指し)」で決める仕組みで、個人のメールアドレスを基準にはできない。", "eg": "イベント会場の入場資格を「公式スタッフ」「身元確認済みの出店者」「招待リストに載っている人」で区切るようなもの。「メールアドレスで入れる」という基準はそもそも設計にない。"}, "gh200-q23": {"point": "Organizationシークレットを一部のリポジトリだけに使わせたいなら、シークレット作成時にSelected repositoriesでアクセス可能なリポジトリを指定する。", "why_asked": "シークレットの公開範囲はワークフロー側ではなく設定側(シークレット作成時のアクセスポリシー)で決まるという「制御する場所」の理解が問われる。ワークフロー側に何を書いても変えられない点を誤解しやすい。", "kid": "どのリポジトリが使えるかは、シークレットを作るときにあらかじめ決めておく設定。後からワークフロー側で操作することはできない。", "eg": "会社の金庫を「どの部署が開けられるか」を、金庫を設置するときに決めておくようなもの。使う側の部署が勝手に権限を広げることはできない。"}, "gh200-q24": {"point": "本番デプロイのジョブ実行前に人の承認を必須にしたいなら、Environmentを作りrequired reviewersを設定し、ジョブにenvironment:を指定する。", "why_asked": "ブランチ保護はマージ時点の制御であり、デプロイジョブの実行前承認とはタイミングが異なる。この「いつ効くか」の違いを理解していないと、承認ゲートをどこに設定すべきか判断を誤る。", "kid": "本番用の実行の前だけ「承認した人がいないと進めない」という関所を置ける仕組みがEnvironmentのrequired reviewers。", "eg": "本番のドアの前に警備員を置いて、ハンコをもらった人しか通さないようにするようなもの。"}, "gh200-q25": {"point": "外部システムからワークフロー実行履歴やアーティファクトをプログラムで扱いたいなら、GitHub REST API(Actionsエンドポイント)を使う。", "why_asked": "YAMLファイルを読む、ランナーにSSHする、といった直感的だが実際には提供されていない/不可能な手段に惑わされず、公式に用意された唯一の窓口(REST API)を選べるかが問われる。", "kid": "外部のプログラムがGitHubの中の実行データを見たり操作したりするための、公式の出入口がREST API。", "eg": "会社の内部データを外部システムから見るには、勝手口(SSHやファイル直読み)ではなく正式な受付窓口(API)を通す必要があるのと同じ。"}, "gh200-q26": {"point": "GITHUB_TOKENに読み取りだけを許したいなら、permissions.contents: readと書く。writeは過剰、noneは不足。", "why_asked": "最小権限の原則(必要な分だけ与える)を実践する上で、read/write/noneの3段階を正確に使い分けられるかが問われる。読み取りすら不要なジョブでは、まずpermissions: {}で全noneにしてから必要分だけ足す発想も実務で重要。", "kid": "「読むだけできればいい」ときはread、「何もさせない」ときはnone、「書き込みも許す」ときはwriteと、必要な分だけ選ぶ。", "eg": "図書館の利用証に「閲覧のみ可」の権限だけを付けるようなもの。持ち出し(書き込み)まで許可する必要はない。"}, "gh200-q27": {"point": "OIDCでクラウドへ短命トークン認証したいなら、permissions.id-token: writeが必須。", "why_asked": "OIDC認証は長期シークレットを使わない代わりに、その場でトークンを発行してもらう権限(id-token: write)を明示しないと機能しない。これを知らないと「シークレットを置いていないのになぜ認証できないか」で詰まる。長期シークレット運用からの移行というセキュリティ文脈でも重視される。", "kid": "使い捨ての入館証(短命トークン)を発行してもらうための「発行許可」がid-token: write。これが無いとトークンをもらえない。", "eg": "長期の合鍵を預けっぱなしにする代わりに、来るたびに使い捨ての入館証を発行してもらう方式。id-token: writeはその発行許可証にあたる。"}, "gh200-q28": {"point": "信頼できない入力(Issueタイトル等)をrunに直接埋め込むと危険。env:に一度バインドしてから\"$VAR\"として参照するのが唯一の本質的対策。", "why_asked": "${{ }}展開はワークフロー実行前にその場で文字列を埋め込む処理であるため、クォートで囲むだけでは展開後にコマンドとして解釈される攻撃を防げない。この展開のタイミングを理解していないと、見かけ上安全に見える誤った対策(クォート、権限を下げる等)を選んでしまう。実務のCI/CDセキュリティ事故に直結するため重点的に問われる。", "kid": "他人が書いた文字列を直接コマンドの中に貼り付けると危険。一度別の場所(環境変数)に移してから「その中身をそのまま表示して」と扱えば、命令として実行されずただの文字データとして安全に扱える。", "eg": "誰かが渡してきたメモをそのまま台本として読み上げる(runに直書き)と、メモに仕込まれた指示まで実行してしまう。一度封筒(環境変数)に入れて「封筒の中身を表示するだけ」にすれば、中身は指示ではなくただのデータになる。"}, "gh200-q29": {"point": "第三者アクションを使う側として改ざんに最も強く固定したいなら、40文字のフルコミットSHAでピン留めする。", "why_asked": "メジャータグ(@v3)や@main、@latestはすべて中身が後から変わりうる「動く参照」であるため、サプライチェーン攻撃(第三者が裏で中身を差し替える)への耐性を考えると、変わらない指紋であるSHAだけが本質的な対策になる。問17(提供側がメジャータグを動かす話)と視点が逆であることに気づけるかが鍵。", "kid": "タグや名前は後から中身を差し替えられてしまうので、絶対に変わらない番号(SHA)で指定すれば、後から中身をすり替えられても気づける。", "eg": "お店で「新商品ください」ではなく「型番◯◯番の商品ください」と指定するようなもの。型番(SHA)を指定しておけば、後から店側が中身をこっそり変えても別物だと気づける。"}, "gh200-q30": {"point": "依存が変わったら確実に新しいキャッシュに切り替わり、かつヒット率も高くしたいなら、hashFiles(ロックファイル)でキーを作りrestore-keysで前方一致フォールバックを用意する。", "why_asked": "固定キーは依存更新後も古いキャッシュを使い続けてしまう事故につながり、逆にSHAやランダムなキーは細かすぎてほぼキャッシュが当たらなくなる。「正確さ(内容が変われば鍵も変わる)」と「当たりやすさ(近い鍵も拾う)」の両方をバランスさせる設計思想が問われる。", "kid": "中身が変わったら鍵も変える(hashFiles)。でも完全一致じゃなくても近い鍵ならなるべく拾う(restore-keys)。この2つを組み合わせると無駄なく速くなる。", "eg": "買い物リストが前回と同じなら買い置きをそのまま使い、リストが変わったら買い直す。多少リストが違っても、似た買い置きがあれば流用する、というくらいの柔軟さを持たせるイメージ。"}, "gh200-q31": {"point": "成果物が誰の・どのワークフローで作られたかを検証可能にし改ざんを検出したいなら、Artifact attestation(来歴/provenance)を使う。", "why_asked": "Dependabot(依存の脆弱性)、Code scanning(コードの静的解析)、Branch protection(マージ制御)はどれもセキュリティ機能として並んで見えるが、守る対象が異なる。「成果物そのものの出所証明」という特有の目的に対応する機能を正確に選べるかが問われる。", "kid": "成果物に「いつ・どこで・誰が作ったか」を証明する封印付きの証明書を付ける機能。後から中身がすり替えられても、証明書と照らし合わせれば気づける。", "eg": "製品に「どの工場のどのラインで、いつ作られたか」を記した封印シールを貼っておくようなもの。後で中身が別物にすり替えられていたら、シールと照合すれば発覚する。"}, "gh200-q32": {"point": "フォークからのpull_requestでは、既定でシークレットは渡されず、GITHUB_TOKENも読み取り中心に制限される。", "why_asked": "見知らぬ第三者のコードが動くフォークPRに対して、GitHub側がどこまで自動的に守ってくれるかという既定の安全策を正確に把握していないと、「全部渡らないから安全」「全部渡るから危険」のどちらかに極端に誤解してしまう。信頼が必要な処理でpull_request_targetを使う際の注意にもつながる基礎知識。", "kid": "知らない人からの提案(フォークPR)には、いきなり金庫の鍵(シークレット)や強い権限を渡さない。読める範囲だけに制限されるのが初期設定。", "eg": "見知らぬ人が「直しておきました」と持ってきた提案に、会社の金庫の鍵をいきなり渡したりしないのと同じ。まずは中身を確認できる範囲(読み取り)だけ許可する。"}, "gh200-q33": {"point": "コスト・時間の削減は「無駄な実行を止める・作業を使い回す・数を減らす」の方向。常時最大スペックで全並列にするのは逆にコスト増になる。", "why_asked": "「スペックを上げれば速くなる=コスト効率が良い」という直感的な誤解に陥りやすい。GitHub-hostedランナーは実行時間の分課金であるため、並列数や実行時間そのものを減らす施策こそが最適化になるという、課金の仕組みに基づいた正しい判断軸が問われる。", "kid": "節約の基本は「無駄な実行をやめる・やり直しを減らす・実行する数を絞る」の3つ。逆に常にフルスペックで全部並列に動かすのはお金を増やす方向になってしまう。", "eg": "家計の節約と同じで、「使っていない電気を消す・同じ買い物をしない・必要な分だけ買う」が節約になる。逆に「いつも一番高いプランをフル稼働させる」のは節約ではなく浪費になる。"}, "gh200-q34": {"point": "Docker container actionのimageには、同梱Dockerfileをビルドする''Dockerfile''か、公開イメージを指すdocker://...のどちらかを指定する。", "why_asked": "composite/node20はそれぞれ別種別のusing値であり、imageキーの値ではない。「using: dockerのときのimageに書ける値は何か」という、種別ごとの正しい組み合わせを区別できるかが問われる(問15のusing: node20との混同対策)。", "kid": "コンテナで動くアクションを作るとき、その場でレシピ(Dockerfile)から作るか、出来合いの缶詰(公開イメージ)を使うかの2択がある。", "eg": "料理を出すとき、自前のレシピでその場で作るか、市販の出来合いの缶詰を使うかを選ぶようなもの。"}, "gh200-q35": {"point": "別リポジトリの再利用可能ワークフローに入力を渡す(呼び出す)側は、withを使う。inputsは受け取る側が定義するキーで役割が逆。", "why_asked": "「渡す側」と「受け取る側」で使うキーが違う(with/inputs)ことを知らないと、reusable workflowを呼び出すときにどちらを書けばいいか迷う。役割の方向を混同しやすい典型例。", "kid": "受け取る側が「こういう項目を受け付けます」という受付票(inputs)を用意し、呼び出す側はその受付票に「with」という記入欄を使って値を書き込む。", "eg": "窓口の受付が用意した申込書の項目(inputs)に対して、申し込む人が記入欄(with)に必要事項を書いて提出するようなもの。"}, "gh200-q36": {"point": "特定のディレクトリ配下が変更されたときだけ起動したいなら、on.push.pathsにglobパターンを指定する。branchesと組み合わせるとAND条件になる。", "why_asked": "branchesとpathsという2種類のフィルターがそれぞれ独立した条件で、両方同時に満たさないと起動しない(AND条件)ことを理解していないと、意図しないタイミングで起動したりしなかったりする不具合に気づけない。files/include/filterといった存在しないキー名との混同対策も含む。", "kid": "ブランチの絞り込み(branches)とファイルの絞り込み(paths)は別々の関門で、両方を通ったときだけ起動する。", "eg": "空港のゲート(branches)を通れても、手荷物検査(paths)で対象の荷物が無ければ先には進めない。両方クリアして初めて起動する。"}, "gh200-q37": {"point": "別ワークフローの完了を待って次のワークフローを起動したいなら、受け取る側でon: workflow_runを宣言する。", "why_asked": "workflow_call(呼び出す側がusesで明示的に呼ぶ)とworkflow_run(受け取る側が完了を検知して自動起動する)は、どちらも「ワークフローを繋げる」仕組みに見えて方向性が逆であるため混同しやすい。needsがジョブ間限定でワークフロー間には使えない点も併せて問われる。", "kid": "前のワークフローが終わったのを見届けてから、次のワークフローが自動的に動き出す仕組み。", "eg": "リレー競走で、前の走者がゴールしたのを見てから次の走者が走り出すバトンパスのようなもの。"}, "gh200-q38": {"point": "今どのイベント(push/pull_requestなど)で動いているかを文字列で知りたいなら、github.event_nameを使う。github.eventは詳細情報の入った別物。", "why_asked": "event_nameとeventは名前が似ているうえ、eventの方が「もっと詳しい情報が入っていそう」に見えて誤って使ってしまいやすい。「イベントの種類の名前」と「イベントの中身(ペイロード)」という役割の違いを正確に区別できるかが問われる。", "kid": "「何のイベントか」という種類の名前が欲しいならevent_name、そのイベントの詳しい中身(PRのタイトルなど)が欲しいならeventを見る。", "eg": "レジで「支払い方法は何ですか(event_name)」と聞かれるのと、「財布の中身を見せてください(event)」と言われるのは別の話。今回欲しいのは支払い方法の種類の方。"}, "gh200-q39": {"point": "前のステップが失敗しても後続ステップを必ず実行したいなら、そのステップにif: always()を付ける。continue-on-errorは失敗そのものの扱いを変える別の設定。", "why_asked": "continue-on-error(失敗を成功扱いにする、対象は失敗する側のステップ)と、if: always()(前が失敗しても自分は実行する、対象は後続のステップ)は、目的も付ける場所も違うのに「失敗しても進める系の設定」として混同されやすい。どちらの立場のステップに何を付けるかの区別が問われる。", "kid": "前のステップが転んでも、後ろのステップは「私は関係なく走ります」と宣言しておける。それがif: always()。", "eg": "リレーで前の走者がバトンを落としても、後ろの走者はコースに出て最後まで走りきる、という取り決めをしておくようなもの。"}, "gh200-q40": {"point": "別ジョブが出力した値を後続ジョブで使いたいなら、needs.<ジョブ名>.outputs.<名前>で参照する。steps.<id>.outputsは同一ジョブ内限定。", "why_asked": "steps.<id>.outputsは同じジョブの中のステップ間でしか通用しない値であり、ジョブをまたぐには一度jobs.<id>.outputsとして外に公開し、needsで受け取る必要があるという2段階の構造を理解していないと、別ジョブから値が見えない原因が分からなくなる。", "kid": "ステップ同士のやり取り(steps.outputs)は同じジョブの中でしか通じない。ジョブをまたいで渡すには、一度外向けの伝票(jobs.outputs)に書き出し、相手はneeds経由でその伝票を読む。", "eg": "工場(buildジョブ)が出荷伝票に品番を書いて出し、倉庫(deployジョブ)がその入荷伝票(needs.build.outputs)を見て品番を確認するようなもの。工場の中だけのメモ(steps.outputs)は倉庫からは見えない。"}, "gh200-q41": {"point": "全ステップ共通のシェルや作業ディレクトリを一括指定したいなら、jobsまたはワークフロー直下のdefaults.runにまとめて書く。", "why_asked": "各ステップに毎回shell: bashやworking-directoryを繰り返し書くと冗長になるだけでなく書き漏れの原因にもなる。settings/options/configのような存在しないキー名との混同対策も含め、DRYにまとめる正しいキー(defaults)を知っているかが問われる。", "kid": "毎回のステップに同じ設定を書く代わりに、まとめて1箇所(defaults)で「これを標準にして」と決めておける。", "eg": "会社の就業規則で服装や勤務時間を一括で決めておけば、社員ごとに毎回説明し直さなくて済むのと同じ。"}, "gh200-q42": {"point": "同じgroupで新しい実行が始まったら、進行中の古い実行をキャンセルして最新だけ残したいなら、concurrency.cancel-in-progress: trueを使う。", "why_asked": "cancel-previousやabort-oldのようなそれらしい名前の非実在キーに惑わされず、正確なキー名(cancel-in-progress)を覚えているかが問われる。concurrencyがジョブレベルにも置けてデプロイの二重実行防止に使われる、という実務上の応用も背景にある。", "kid": "同じグループで新しい実行が始まったとき、前の実行中のものを打ち切って最新だけ残す設定。", "eg": "エレベーターを何度も連打すると、最初の呼び出しは取り消されて最後に押した行き先だけが有効になるのと同じ。"}, "gh200-q43": {"point": "ジョブが暴走(無限ループ等)しても一定時間で強制終了させたいなら、jobs.<id>.timeout-minutesに分数を指定する。", "why_asked": "既定のタイムアウトが360分(6時間)と長いため、これを知らずに無限ループ等のバグが起きると、気づかないまま長時間クレジットを消費し続けてしまう。max-duration等の存在しないキー名との混同対策も兼ねる。", "kid": "設定した時間が来たら、まだ動いていても強制的に止める安全装置。無限ループで課金が延々と続くのを防ぐ。", "eg": "電子レンジのタイマーのようなもの。まだ調理中でも設定時間が来れば自動で止まる。"}, "gh200-q44": {"point": "テストジョブが失敗してもキャンセルされても後片付けを必ず実行させたいなら always()。needs があるとデフォルトは success() 相当になる点とセットで覚える。", "why_asked": "needs で依存関係を作ったジョブは、明示しない限り前ジョブの成功が前提になる。この暗黙のデフォルトを知らないと「クリーンアップジョブがテスト失敗時だけ動かない」という実運用の事故につながるため、GH-200で繰り返し問われる。", "kid": "テストが失敗しても中止(キャンセル)されても、片付けジョブだけは絶対に動かしたいときは always() を使う。", "eg": "台風が来ても来なくても、閉店後は必ず店を掃除するのと同じ。掃除(片付けジョブ)は営業成績(テスト結果)に関係なく毎回やる。"}, "gh200-q45": {"point": "owner/repo形式のリポジトリ名がほしいなら github コンテキストの repository。env・runner・job のような似た名前のコンテキストと混同しない。", "why_asked": "github/env/runner/job/steps という複数のコンテキストが並んでいて、どの情報がどのコンテキストに属するかを正確に覚えていないと、名前が似ている選択肢に引っかかってしまう。", "kid": "リポジトリの名前が知りたいときは、そのワークフロー実行についての情報がまとまった github という箱から repository を取り出す。", "eg": "住民票を取りたいなら市役所(githubコンテキスト)に行く。会社の入館証(runnerコンテキスト)を見てもその人の住所はわからない。"}, "gh200-q46": {"point": "「実行間で依存関係を再利用して速くしたい」なら actions/cache。「成果物を保存して後で見る・使う」なら upload-artifact、と目的で切り分ける。", "why_asked": "cache と upload-artifact はどちらも「何かを保存する」という点で似て見えるため混同しやすい。実務でも高速化のために使うべき cache の代わりに artifact を使ってしまうミスが起きやすい。", "kid": "毎回同じライブラリをダウンロードし直すのは無駄なので、前回のダウンロード結果をしまっておいて次回また使い回す仕組みが cache。", "eg": "引っ越すたびに家具を新品で買うのではなく、倉庫に預けておいた家具をまた取り出して使うのと同じ。"}, "gh200-q47": {"point": "ステップ間で値を渡すなら $GITHUB_OUTPUT に書き込んで steps.<id>.outputs.<key> で読む。::set-output は廃止済みなので選ばない。", "why_asked": "::set-output は長く使われてきた古い書き方で、今も古い記事やコードに残っているため、廃止された理由(コマンドインジェクション対策)ごと知らないと誤って選んでしまう。", "kid": "前のステップで作った値を次のステップに渡したいときは、決められたファイル(GITHUB_OUTPUT)にメモを書いておき、そのメモを次のステップが読みに行く。", "eg": "伝言板に書き置きを残しておき、次の人がその伝言板を見に行くイメージ。昔のFAX(::set-output)はもう使われていない。"}, "gh200-q48": {"point": "読むだけで書き込みが不要なら contents: read。write は過剰、none はcloneすら不可、read-write は存在しない値なので選ばない。", "why_asked": "最小権限の原則はセキュリティ領域の頻出テーマ。GITHUB_TOKEN は放っておくと広い権限を持ちがちなので、必要な分だけ read 等に絞る発想が問われる。", "kid": "読むだけでいい仕事に書き込みの権限まで渡さない。読む専用の鍵(read)だけ渡しておけば十分。", "eg": "図書館で本を読むだけの人に本を書き換える権限は不要。読書カード(read)だけ渡せば十分なのと同じ。"}, "gh200-q49": {"point": "複数ジョブでファイル(バイナリなど)を共有したいなら upload-artifact と download-artifact の組み合わせ。GITHUB_OUTPUT は文字列専用、cache はキーが一致したときだけ復元される仕組みで確実な受け渡しには向かない。", "why_asked": "ジョブ間でデータをやり取りする手段(output・artifact・cache)が複数あり、それぞれ「文字列かファイルか」「確実な受け渡しか高速化目的か」という適用範囲が違うため、混同させる出題が多い。", "kid": "ビルドで作った実物のファイルを他のジョブにも渡したいときは、共有の置き場(artifact)に一度アップロードして、他のジョブがそこからダウンロードする。", "eg": "作った資料を共有フォルダにアップロードしておき、複数の人がそれぞれダウンロードして使うのと同じ。"}, "gh200-q50": {"point": "再利用可能ワークフローが呼び出し元から値を受け取るなら workflow_call 配下の inputs で定義する。parameters・args・variables は存在しないキー。", "why_asked": "再利用可能ワークフローの仕組みは関数呼び出しに近いが、独自のキー名(inputs・secrets)を正確に覚えていないと構文エラーになるため、名前の暗記そのものが問われる。", "kid": "呼び出し先のワークフローが「こんな値をもらえます」と宣言しておく場所が inputs。", "eg": "関数の引数を定義するのと同じで、呼び出す側が with で値を渡し、呼び出される側は inputs でその値を受け取る。"}, "gh200-q51": {"point": "ステップの詳細なデバッグログを見たいなら ACTIONS_STEP_DEBUG というシークレット(または変数)を true にする。YAMLのキーやCLIフラグでは有効化できない。", "why_asked": "トラブルシューティング領域の定番設定。debug: true のようなYAMLキーは存在しないという、ありそうで無い引っかけに注意する必要がある。", "kid": "普段は表示されない詳しいログを見たいときは、設定画面にあるスイッチ(ACTIONS_STEP_DEBUG)をオンにする。", "eg": "家電の隠れた詳細モードを設定メニューから有効にするのに似ている。ワークフローのファイルを書き換えるのではなく、リポジトリの設定画面から入れる。"}, "gh200-q52": {"point": "再利用可能ワークフローの結果を呼び出し元で受け取るなら、workflow_call.outputs で公開し、呼び出し元は needs.<job>.outputs で参照する。", "why_asked": "inputs(値を渡す)と outputs(値を返す)は対になる仕組みで、呼び出し元での参照のしかた(needs.*.outputs)まで含めて実務で頻出しつつ間違えやすい。", "kid": "再利用可能ワークフローが「この値を返します」と宣言しておき、呼び出した側はneeds経由でその値を受け取る。", "eg": "発注先の工場が納品書に出来上がった数量を書き、発注元がその納品書を見て確認するのと同じ。"}, "gh200-q53": {"point": "失敗したジョブだけをやり直したいなら実行詳細画面の「Re-run failed jobs」を使う。retry: true のような存在しないYAMLキーは選ばない。", "why_asked": "再実行の操作がUI操作なのかYAML設定なのか混同しやすく、CIを日常的に回すうえで時間を無駄にしないために知っておくべき操作。", "kid": "全部やり直すのではなく、失敗した部分だけをもう一度実行するボタンが実行画面にある。", "eg": "テストで間違えた問題だけ解き直すのと同じで、すでに正解した問題(成功したジョブ)はやり直さなくていい。"}, "gh200-q54": {"point": "ステータスバッジのURLはリポジトリのactions/workflows/配下にワークフローの「ファイル名」を入れる形。ワークフロー名(name:)や外部サービスのURLとは区別する。", "why_asked": "READMEにCIバッジを貼る実務作業で、表示上の名前とファイル名を混同したURLを書いてバッジが表示されないというハマりどころがあるため。", "kid": "バッジの住所には、ワークフローに付けた表示名ではなくYAMLファイルの名前を使う。", "eg": "表札の名前(ワークフロー名)ではなく、部屋番号(ファイル名)を指定して郵便物を届けるようなもの。"}, "gh200-q55": {"point": "マージ前に特定のチェックを必須にしたいなら、Settings→Branchesのブランチ保護ルールでRequire status checksを設定する。", "why_asked": "CIを「強制する」設定はワークフローのYAML側にあると誤解しやすいが、実際はリポジトリ設定(ブランチ保護)側にあるという、設定の所在の理解が問われる。", "kid": "マージする前に必ずこのテストが通っていること、というルールはブランチの保護設定のほうで決める。", "eg": "マンションの入り口に警備員を置いて、身分証チェック(ステータスチェック)が通らないと中に入れないようにする仕組み。"}, "gh200-q56": {"point": "forkからのpull_requestは制限されたトークンでチェックアウトされるので、通常のactions/checkoutをそのまま使えば安全。特別なオプションや別トリガーへの切り替えは不要。", "why_asked": "fork PRのセキュリティモデル(pull_request と pull_request_target の違い)はセキュリティ領域の頻出テーマで、安全な既定動作をわざわざ危険な代替に変えてしまう誤答を誘いやすい。", "kid": "知らない人が送ってきたコード(fork PR)は、機密情報を持たない安全な部屋(制限されたトークン)の中で動かすので、普段通りのcheckoutで問題ない。", "eg": "面接に来た初対面の人を、会社の金庫がない応接室に通して面談するようなもの。"}, "gh200-q57": {"point": "どのステップが失敗したか特定したいなら、まず実行詳細画面でジョブを開き、赤くなっているステップのログを見る。", "why_asked": "障害対応の最初の一歩として最も基本的な操作。サマリー表示や全体トレンドなど「関係ありそうで的外れな情報源」を選ばせる引っかけがある。", "kid": "エラーが起きたら、まず画面で赤く表示されているところをクリックして詳しいログを読む。", "eg": "健康診断の結果表で、まず異常値(赤字)の項目からチェックするのと同じ。"}, "gh200-q58": {"point": "特定のステップの成否だけを条件分岐に使いたいなら steps.<id>.outcome を参照する。result や status という名前のプロパティは存在しない。", "why_asked": "outcomeとconclusionの違い(continue-on-error適用前か後か)は紛らわしく、「特定ステップの結果を見る」という頻出パターンでの定番の引っかけになっている。", "kid": "「あのステップだけ失敗したか」を知りたいときは、そのステップのid.outcomeを見る。", "eg": "下駄を履かせる前の素の答案(outcome)を見るか、補正後の成績通知(conclusion)を見るかの違いで、今回知りたいのは素の結果なのでoutcomeを使う。"}, "gh200-q59": {"point": "シェルの複数ステップをまとめて再利用したいだけならComposite actionが最もシンプル。Node.jsやDockerfileが必要な他の種類は過剰。", "why_asked": "Composite・JavaScript・Dockerの3種類のアクションの使い分けは頻出で、実装コストと用途のバランスを理解しているかが問われる。", "kid": "シェルコマンドをいくつかまとめて1つの部品にしたいだけなら、特別な準備がいらないComposite actionを使う。", "eg": "出来合いの料理を弁当箱に詰めるだけ(Composite)で済むのに、わざわざキッチンを一から作る(Docker)必要はない。"}, "gh200-q60": {"point": "Composite actionのrunステップではshellの指定が必須。通常のワークフローYAMLでは省略できるのに、Composite actionだけは省略できないという例外を覚える。", "why_asked": "「通常のワークフローでは省略できるがComposite actionでは必須」という非対称なルールが、そのまま試験の引っかけになりやすいため。", "kid": "普段は書かなくていいはずのshell指定が、Composite actionの中だけは必ず書かないとエラーになる。", "eg": "普段は暗黙の了解で済むはずのルールが、ある特定の場所だけは必ず明文化しないといけないようなもの。"}, "gh200-q61": {"point": "JavaScript actionでステップを失敗として終わらせたいならcore.setFailed()を呼ぶ。core.error()は警告表示だけでステップを失敗にはしない。", "why_asked": "core.error・core.setFailed・process.exitはどれもエラーっぽく見えるが、実際にステップを失敗扱いにする正式なAPIはsetFailedだけという区別が問われる。", "kid": "ただ赤い警告を出すだけ(error)ではジョブは止まらない。ジョブ自体を失敗させたいならsetFailedを呼ぶ必要がある。", "eg": "警告ランプを光らせるだけと、非常ベルを鳴らして避難させるくらいの違いがある。setFailedは非常ベルの役目。"}, "gh200-q62": {"point": "Dockerコンテナアクションで実行するスクリプトを指定するにはentrypointキーを使う。Composite用のrunやDocker本来の用語cmdと混同しない。", "why_asked": "action.yml内のキー名はDocker本来の用語(ENTRYPOINT/CMD)とは微妙に違う独自の呼び方をするため、素のDocker知識だけでは誤答しやすい。", "kid": "どのファイルを実行のスタート地点にするかを、action.ymlの中でentrypointという項目に書く。", "eg": "レストランで最初に指名するシェフを決めるようなもので、Dockerfileに書かれたシェフを別のシェフ(entrypoint)に差し替えられる。"}, "gh200-q63": {"point": "Marketplaceに公開する最低条件は、公開リポジトリのルートにaction.ymlを置くこと。タグ付けやREADMEの充実は推奨だが必須ではない。", "why_asked": "「推奨されること」と「必須条件」を混同しやすい。試験は実際には無くても公開できる要素(タグ・README・organization名)を選択肢に混ぜて区別させてくる。", "kid": "お店を開くのに看板(action.yml)は絶対必要だが、開店祝いの飾りつけ(README充実やタグ)は無くても開店できる。", "eg": "店を出すには最低限「店の名前を書いた看板」があればよく、豪華な内装は無くても営業自体は始められる。"}, "gh200-q64": {"point": "サードパーティアクションのセキュリティを最優先するなら、書き換えられないコミットSHAで固定する。タグやmainブランチ参照は後から中身が変わりうるので避ける。", "why_asked": "サプライチェーン攻撃対策としてSHA固定が公式に推奨されており、GH-200のセキュリティ領域の定番。タグ参照(vX)は「普通のバージョン管理」に見えるため誤答しやすい。", "kid": "バージョン名(タグ)は後から中身をすり替えられることがあるが、コミットのハッシュ(SHA)は絶対に変わらないので一番安全。", "eg": "本のタイトル(タグ)だけ指定すると改訂版に差し替わることがあるが、ISBN番号(コミットSHA)を指定すれば同じ内容であることが保証される。"}, "gh200-q65": {"point": "inputsに値が渡されなかったときの既定値はdefaultキーで指定する。fallback・initial・placeholderは存在しないキー。", "why_asked": "プログラミング言語でよく聞く似た語感の単語(fallback等)から正しいキー名を推測させる、用語の正確な暗記が問われる出題のため。", "kid": "何も渡されなかったときに自動で使われる値を、defaultという項目にあらかじめ書いておく。", "eg": "注文で何も指定しなかったら「本日のおすすめ」が自動で出てくる仕組みで、そのおすすめの中身を決めているのがdefault。"}, "gh200-q66": {"point": "メイン処理の後に必ず後片付けをしたいなら、action.ymlのruns.postに後処理スクリプトを指定する。process.on(''exit'')やワークフロー側の別ステップでは代用しない。", "why_asked": "runs.mainとruns.postの対応、pre/main/postというアクションのライフサイクルの理解はJavaScript action作成領域の頻出知識のため。", "kid": "メインの処理が終わった後に自動で動く「片付け専用」の場所がruns.post。", "eg": "工事が終わった後、業者が現場を掃除してから帰るように、メイン作業とは別に後片付けの担当が用意されている。"}, "gh200-q67": {"point": "JavaScript actionでNode.js 20を使うならusing: node20と書く。nodejs20・node・jsのような似ているが違う表記は存在しない。", "why_asked": "ランタイム識別子の正確な文字列を覚えているかがそのまま問われる。node16など旧バージョンから新しいnode20への移行時期の知識も絡むため。", "kid": "どのバージョンのNode.jsで動かすかを、node20という決まった書き方で指定する。", "eg": "家電のコンセントの規格を正確に指定しないと動かないのと同じで、node20という正確な表記でないとエラーになる。"}, "gh200-q68": {"point": "color/iconはGitHub Marketplaceでの見た目(アイコンと背景色)を設定するもので、実行ログやステータスチェックの見た目には影響しない。", "why_asked": "brandingという言葉から実行時の見た目全般に効くと誤解しやすいが、実際の効果範囲はMarketplaceの一覧表示だけという限定性が問われるため。", "kid": "colorとiconは、お店(Marketplace)に並んだときの見た目を決めるだけで、ワークフローを実行しているときの画面には関係ない。", "eg": "商品パッケージのデザインは店頭に並んだときに目立つためのもので、中身の動作には関係ないのと同じ。"}, "gh200-q69": {"point": "複数ラベルを全部満たすランナーを選びたいなら配列で列挙する。self-hostedラベルを含めないと、意図せずホスト型ランナーが選ばれる可能性がある点に注意。", "why_asked": "runs-onへの配列指定はAND条件になるという仕様の理解と、self-hostedラベルを省略した場合の意図しない挙動という実務の落とし穴の両方が問われるため。", "kid": "「gpuもhigh-memoryも両方持っているランナー」を選びたいときは、条件を配列で全部書き並べる。", "eg": "タクシー配車アプリで「SUVかつペット可」の車を探すのと同じで、条件をすべて満たす1台だけが選ばれる。"}, "gh200-q70": {"point": "特定のリポジトリだけにセルフホストランナーを使わせたいなら、ランナーグループを作りアクセス範囲を制限する。ラベルはランナーの選び方に使うだけでアクセス制御の機能ではない。", "why_asked": "ラベル(どのランナーを選ぶか)とランナーグループ(誰がそのランナーを使えるか)は役割が違うのに響きが似ていて混同しやすいため。", "kid": "どのリポジトリがそのランナーを使えるかを決めるのはランナーグループの役割で、ラベルの役割ではない。", "eg": "会社の特別な会議室を使える部署を制限するのは、案内板の名前ではなく入室許可リストの仕事なのと同じ。"}, "gh200-q71": {"point": "使っていいアクションの範囲を組織全体で決めたいなら、組織のActions permissionsで設定する。リポジトリ側の設定は組織のポリシー範囲内でしか変えられない。", "why_asked": "組織レベルとリポジトリレベルの設定の親子関係(組織が制限すればリポジトリはそれより緩められない)を理解しているかが問われるため。", "kid": "どのアクションを使っていいかという大枠のルールは組織全体の設定画面で決め、各リポジトリはそのルールの範囲内でしか動けない。", "eg": "会社の購買規定で「承認済みの取引先からしか買えない」と決めたら、各部署はその規定の中でしか発注できないのと同じ。"}, "gh200-q72": {"point": "全組織から使えるランナーを一元管理したいならエンタープライズレベルで登録する。組織単位やリポジトリ単位の登録では共有できる範囲が狭くなる。", "why_asked": "ランナーの登録先(リポジトリ・組織・エンタープライズ)は階層構造になっており、共有範囲の広さと管理単位を対応づけて理解しているかが問われるため。", "kid": "全部の部署(組織)が使えるようにしたいなら、一番上のレベル(エンタープライズ)に登録する。", "eg": "本社に共用の会議室を作れば全部署が使えるが、各部署の階だけに置くとその部署しか使えないのと同じ。"}, "gh200-q73": {"point": "セルフホストランナーを止めると、実行中のジョブは他のランナーに自動で移らずタイムアウトして失敗する。GitHubホストランナーのような自動復旧はない。", "why_asked": "GitHubホスト型ランナーとセルフホストランナーの信頼性・運用責任の違いは実務で重要で、メンテナンス手順(ドレイン)を知らずに突然止めると障害を招くため試験でも問われる。", "kid": "セルフホストのランナーを急に止めると、そこで動いていた作業は他の場所に引き継がれず、そのまま失敗してしまう。", "eg": "配達中のトラックが急に止まっても、荷物は自動で別のトラックに積み替えられず、その場で止まってしまうのと同じ。"}, "gh200-q74": {"point": "長期間有効な秘密鍵を保存せずにクラウド認証したいならOIDCで一時クレデンシャルを取得する。シークレットの保存場所を組織や環境に変えるだけでは根本的なリスクは減らない。", "why_asked": "長期シークレットの漏洩リスクを減らす仕組みとしてOIDCは公式に強く推奨されており、「保存場所を工夫すれば安全」という誤答との区別がねらいのため。", "kid": "毎回使い捨ての合言葉(一時クレデンシャル)をその場で発行してもらえば、長く使えるパスワードを保管しておく必要がなくなる。", "eg": "会社訪問のたびに使い捨ての来客バッジを受付で発行してもらうようなもので、永久に使える社員証を渡しておく必要がない。"}, "gh200-q75": {"point": "Kubernetes上でセルフホストランナーをジョブキューに応じて自動スケールさせたいならActions Runner Controller(ARC)を使う。CPU・メモリ基準のHPA単体ではキューの深さに反応できない。", "why_asked": "Kubernetesの一般知識(HPA)だけでは解けず、GitHub Actions固有の公式ツール(ARC)を知っているかどうかがそのまま問われるため。", "kid": "待っているジョブの数に応じてランナーの数を自動で増減させてくれる、Kubernetes用の専用の仕組みがARC。", "eg": "混雑具合に応じてレジの数を自動で増減するスーパーのシステムのようなもの。"}, "gh200-q76": {"point": "組織でIP許可リストを有効にしている場合、セルフホストランナーが動くマシンの送信元IPを許可リストに追加しないとGitHubへの通信が拒否される。", "why_asked": "IP許可リストは「外からGitHubにアクセスする側」を制限する機能で、ランナー自身もその制限の対象になるという方向性を正しく理解しているかが問われるため。", "kid": "ランナーもGitHubに向かって通信するので、そのランナーのIPアドレスも許可リストに載せておかないと弾かれてしまう。", "eg": "来客リストに自社の配達員の名前を載せ忘れると、受付で入館を断られてしまうのと同じ。"}, "gh200-q77": {"point": "全組織・全リポジトリに特定のワークフローを必ず実行させたいなら、エンタープライズレベルのRequired workflows(必須ワークフロー)を使う。ブランチ保護やCODEOWNERSはリポジトリ単位の設定でスコープが足りない。", "why_asked": "組織横断でセキュリティ基準を統一するのは大企業ならではの実務課題で、リポジトリ単位の設定を積み重ねてしまう誤答との区別がねらいのため。", "kid": "全部のリポジトリに「このチェックは必ず実行してね」と一括で強制できる仕組みが必須ワークフロー。", "eg": "マンション全体の管理規約で「全戸が消防点検を受けること」と決めれば、各部屋ごとに個別のルールを作る必要がなくなるのと同じ。"}, "gh200-q78": {"point": "書き込みが一切不要ならpermissions: read-allで全スコープを読み取り専用にする。空オブジェクト{}にすると全部noneになりcheckoutすら失敗する点に注意。", "why_asked": "permissionsの省略記法(read-all・write-all・{})はそれぞれ効果が異なり、特に{}が「全部none」になるという直感に反する挙動が引っかけになりやすいため。", "kid": "何も書き込まない仕事には、全部読めるだけの権限(read-all)を渡せば十分で、それ以上は不要。", "eg": "全部屋を覗ける鍵(read-all)だけ渡せば、何も持ち出さない見学者には十分。全部の鍵(write-all)を渡す必要はない。"}, "gh200-q79": {"point": "untrusted inputをシェルコマンドで使うときは、${{ }}を直接run:に書かず、いったんenv経由の環境変数に代入してから参照する。", "why_asked": "スクリプトインジェクションはセキュリティ領域の重要トピックで、issueタイトルなど外部から書き換え可能な値を直接埋め込む危険なパターンを避けられるかが問われるため。", "kid": "外から来た値をそのままコマンドに書き込むと危険なので、いったん安全な入れ物(環境変数)に移してから使う。", "eg": "得体の知れない食材を直接火にくべるのではなく、いったん容器に入れてから調理するようなもの。"}, "gh200-q80": {"point": "pull_request_targetはベースリポジトリの文脈でシークレットにアクセスできるため、fork PRのコードを直接チェックアウトして実行すると、その悪意あるコードにシークレットを読み取られる危険がある。", "why_asked": "pull_request(安全)とpull_request_target(危険になりうる)の違いはセキュリティ領域で繰り返し問われる最重要ポイントの1つのため。", "kid": "pull_request_targetは金庫の鍵(シークレット)を持ったまま、知らない人が書いたコード(fork)を動かしてしまう危険な組み合わせ。", "eg": "金庫のある部屋に見知らぬ訪問者を通した上で、その訪問者が持ち込んだ道具を自由に使わせてしまうようなもの。"}, "gh200-q81": {"point": "サードパーティアクションのバージョンを自動更新したいならDependabotのpackage-ecosystem: github-actionsを設定する。手動監視や自作ワークフローより公式の仕組みを使う。", "why_asked": "依存関係の自動更新というとnpmやpipのイメージが強いが、GitHub Actions自体もDependabotの対象になるという範囲の広さを知っているかが問われるため。", "kid": "ワークフローの中で使っているアクションが古くなっていないか、Dependabotが自動でチェックして更新のPRを作ってくれる。", "eg": "アプリのライブラリを自動更新してくれるのと同じ仕組みが、ワークフローの部品(アクション)にも使える。"}, "gh200-q82": {"point": ".github/workflows/の変更にセキュリティチームのレビューを必須にしたいなら、CODEOWNERSでそのパスをチームに割り当て、さらにブランチ保護でCODEOWNERSレビューを必須化する2段構えが必要。", "why_asked": "CODEOWNERSだけでは強制力がなく、ブランチ保護と組み合わせて初めて「必ずそのチームの承認が要る」という強制になる、という2機能の連携が問われるため。", "kid": "「このフォルダを変えるときはこの人たちがレビューする」という担当割り当てと、「その担当のレビューがないとマージできない」という強制の2つを組み合わせて初めて必須になる。", "eg": "重要書類の変更に法務部の印鑑が必要だと決め、さらに印鑑がない書類は受け付けないという2つのルールをセットにするようなもの。"}, "gh200-q83": {"point": "PRにコメントを追加するにはpull-requests: writeが必要。readは閲覧のみでコメント投稿はできない。", "why_asked": "権限スコープごとに「読み取りでできること」と「書き込みが必要なこと」の境界線を正確に覚えているかが問われるため。", "kid": "PRを読むだけならreadでいいが、コメントという新しい書き込みをするにはwriteの権限が必要。", "eg": "掲示板を読むだけなら誰でもできるが、掲示板に書き込むには書き込み権限が必要なのと同じ。"}, "gh200-q84": {"point": "特定メンバーによる手動承認をデプロイ前に必須にしたいなら、Settings→Environmentsのproduction環境でRequired reviewersを設定する。if条件やブランチ保護では代用できない。", "why_asked": "Environmentsという機能自体(承認ゲート・待機タイマー・環境専用シークレットをまとめて持つ)の存在と、それが唯一の公式な人手承認の仕組みであることが問われるため。", "kid": "デプロイする前に人間の承認を待たせたいときは、Environmentsの設定で承認者を指定しておく。", "eg": "工場の出荷ゲートで品質管理担当のOKが出るまでトラックが出発できない仕組みと同じ。"}, "gh200-q85": {"point": "同名シークレットが環境・リポジトリ・組織の3階層にある場合、最もスコープが狭い環境シークレットが優先される。値が結合されることはない。", "why_asked": "シークレットのスコープ階層と優先順位はセキュリティ設計上重要で、「広い範囲の設定が勝つ」と誤解しやすいところを正しく理解しているかが問われるため。", "kid": "同じ名前のシークレットが複数の場所にあっても混ざったりはせず、一番狭い範囲(環境)の値だけが使われる。", "eg": "マトリョーシカ人形の一番内側の値が最終的に使われるようなもので、外側(組織)の値は内側(環境)があれば無視される。"}}'::jsonb) AS v(key, value)
WHERE q.source_ref = v.key
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'gh-200')
  AND q.explanation_data IS NOT NULL;

COMMIT;
